package ActionsControl_1ConditionalIfElse {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        if  condition  {
           perform  A ;
        }  else  {
           perform  B ;
        }
    }

    view ExposeExample {
        expose Main;
    }
}

package ActionsControl_2Loops {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        while  x < 10  {
           perform  A ;
        }
        for  i  in  1..5  {
           perform  B (i) ;
        }
    }

    view ExposeExample {
        expose Main;
    }
}

package ActionsControl_3Assignments {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        action  Defs  {
           attribute  x  :  Integer ;
           assign  x  :=  42 ;
        }
    }

    view ExposeExample {
        expose Main;
    }
}

package ActionsControl_4DecisionMerge {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        action  DecisionFlow  {
           decide  d1 ;
           merge  m1 ;
           first  start ;
           then  d1 ;
           then  m1  if  condition ;
        }
    }

    view ExposeExample {
        expose Main;
    }
}

package ActionsControl_5ForkJoin {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        action  ParallelFlow  {
           fork  f1 ;
           join  j1 ;
           then  f1 ;
           then  a  from  f1 ;
           then  b  from  f1 ;
           then  j1  from  a ,  b ;
        }
    }

    view ExposeExample {
        expose Main;
    }
}

package ActionsControl_6GroupAction {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        group  {
           perform  A ;
           perform  B ;
        }
    }

    view ExposeExample {
        expose Main;
    }
}
